/**
 * React Router building blocks for the Next App Router file conventions. src/spa/routes.gen.tsx
 * (generated by scripts/gen-routes.mjs from src/app) composes these:
 *
 *   Next segment:  Layout > ErrorBoundary(error.tsx) > Suspense(loading.tsx) > children
 *   here:          lazySegment()  — the same nesting around an <Outlet/>
 *   Next page:     page.tsx with { params: Promise, searchParams: Promise } + metadata
 *   here:          lazyPage()     — PageHost passes already-resolved promises and applies metadata
 */
import { Children, isValidElement, Suspense, useEffect, useRef, type ComponentType, type ReactElement, type ReactNode } from "react";
import { Outlet, ScrollRestoration, useLocation, useParams, useRouteError, type RouteObject } from "react-router";
import type { Metadata } from "next";
import { ClientRedirect, SegmentBoundary, type ErrorComponent } from "./boundary";
import { applyMetadata, type MetadataTemplate } from "./metadata";
import { toNextParams } from "./shims/navigation";
import { onPathChange } from "./session";

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- page modules have per-page prop types
type AnyComponent = ComponentType<any> | ((props: any) => unknown);
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Mod<T = AnyComponent> = { default: T; metadata?: Metadata; generateMetadata?: (props: any, parent: any) => Promise<Metadata> | Metadata };
type Loader<T = AnyComponent> = () => Promise<Mod<T>>;

/* ------------------------------------------------------------------ metadata template */

const APP_NAME = process.env.NEXT_PUBLIC_APP_NAME ?? "Tech Drona";
let template: MetadataTemplate = { default: APP_NAME, template: `%s · ${APP_NAME}` };

function templateFrom(md: Metadata | undefined): MetadataTemplate | null {
  const t = md?.title;
  if (t && typeof t === "object") return { default: t.default ?? t.absolute ?? APP_NAME, template: t.template ?? null };
  if (typeof t === "string") return { default: t, template: null };
  return null;
}

/* ------------------------------------------------------------------ stable promises */

type Thenable<T> = Promise<T> & { status?: string; value?: T };
const resolved = new Map<string, Thenable<unknown>>();

/** A promise that React's `use()` reads synchronously, the same object for the same value. */
function stableResolved<T>(key: string, value: T): Promise<T> {
  let p = resolved.get(key) as Thenable<T> | undefined;
  if (!p) {
    p = Promise.resolve(value) as Thenable<T>;
    p.status = "fulfilled";
    p.value = value;
    resolved.set(key, p as Thenable<unknown>);
    if (resolved.size > 200) {
      const first = resolved.keys().next().value;
      if (first !== undefined) resolved.delete(first);
    }
  }
  return p;
}

export function searchToRecord(search: string): Record<string, string | string[]> {
  const out: Record<string, string | string[]> = {};
  for (const [k, v] of new URLSearchParams(search)) {
    const prev = out[k];
    if (prev === undefined) out[k] = v;
    else out[k] = Array.isArray(prev) ? [...prev, v] : [prev, v];
  }
  return out;
}

/* ------------------------------------------------------------------ pages */

function PageHost({ mod, catchAll }: { mod: Mod; catchAll?: string }) {
  const rr = useParams();
  const location = useLocation();
  const params = toNextParams(rr as Record<string, string | undefined>, catchAll);
  const pKey = JSON.stringify(params);
  const paramsP = stableResolved(`p:${pKey}`, params);
  const searchP = stableResolved(`s:${location.search}`, searchToRecord(location.search));

  useEffect(() => {
    let alive = true;
    if (mod.generateMetadata) {
      Promise.resolve()
        .then(() => mod.generateMetadata?.({ params: paramsP, searchParams: searchP }, Promise.resolve({ title: null })))
        .then((md) => alive && applyMetadata(md, template))
        .catch(() => alive && applyMetadata(mod.metadata, template));
    } else applyMetadata(mod.metadata, template);
    return () => {
      alive = false;
    };
  }, [mod, paramsP, searchP, location.key]);

  const Page = mod.default as ComponentType<{ params: Promise<unknown>; searchParams: Promise<unknown> }>;
  return <Page params={paramsP} searchParams={searchP} />;
}

export function lazyPage(load: Loader, catchAll?: string): NonNullable<RouteObject["lazy"]> {
  return async () => {
    const mod = await load();
    return { Component: () => <PageHost mod={mod} catchAll={catchAll} /> };
  };
}

/* ------------------------------------------------------------------ segments */

interface SegmentParts {
  Layout?: ComponentType<{ children: ReactNode }>;
  ErrorView?: ErrorComponent;
  Loading?: ComponentType;
}

function SegmentBody({ ErrorView, Loading, notFound }: SegmentParts & { notFound?: ComponentType }) {
  const inner = Loading ? (
    <Suspense fallback={<Loading />}>
      <Outlet />
    </Suspense>
  ) : (
    <Outlet />
  );
  return (
    <SegmentBoundary errorComponent={ErrorView} notFound={notFound}>
      {inner}
    </SegmentBoundary>
  );
}

function makeSegment(parts: SegmentParts) {
  const { Layout } = parts;
  return function Segment() {
    const body = <SegmentBody {...parts} />;
    return Layout ? <Layout>{body}</Layout> : body;
  };
}

export function lazySegment(files: { layout?: Loader<ComponentType<{ children: ReactNode }>>; error?: Loader<ErrorComponent>; loading?: Loader<ComponentType> }): NonNullable<RouteObject["lazy"]> {
  return async () => {
    const [layout, error, loading] = await Promise.all([files.layout?.(), files.error?.(), files.loading?.()]);
    return { Component: makeSegment({ Layout: layout?.default, ErrorView: error?.default, Loading: loading?.default }) };
  };
}

/* ------------------------------------------------------------------ root */

function PathWatcher() {
  const { pathname } = useLocation();
  const prev = useRef<string | null>(null);
  useEffect(() => {
    onPathChange(prev.current, pathname);
    prev.current = pathname;
  }, [pathname]);
  return null;
}

/** Strip a global-error's own <html>/<body> (the SPA mounts inside #root). */
function bodyContent(node: ReactNode): ReactNode {
  const childrenOf = (el: ReactElement) => (el as ReactElement<{ children?: ReactNode }>).props.children;
  let cur: ReactNode = node;
  if (isValidElement(cur) && cur.type === "html") {
    cur = Children.toArray(childrenOf(cur)).find((c) => isValidElement(c) && c.type === "body") ?? null;
  }
  if (isValidElement(cur) && cur.type === "body") return childrenOf(cur);
  return cur;
}

export interface RootFiles {
  layout: Mod<ComponentType<{ children: ReactNode }>>;
  error?: Mod<ErrorComponent>;
  notFound: Mod<ComponentType>;
  globalError?: Mod<ErrorComponent>;
  children: RouteObject[];
  redirects?: RouteObject[];
}

export function rootRoute(files: RootFiles): RouteObject {
  template = templateFrom(files.layout.metadata) ?? template;
  const Layout = files.layout.default;
  const NotFoundView = files.notFound.default;
  function NotFound() {
    useEffect(() => applyMetadata(files.notFound.metadata, template), []);
    return <NotFoundView />;
  }
  function Root() {
    return (
      <Layout>
        <PathWatcher />
        <ScrollRestoration />
        <SegmentBoundary errorComponent={files.error?.default} notFound={NotFound}>
          <Suspense fallback={null}>
            <Outlet />
          </Suspense>
        </SegmentBoundary>
      </Layout>
    );
  }
  const GlobalErrorView = files.globalError?.default;
  function RootError() {
    const error = useRouteError();
    const err = error instanceof Error ? error : new Error(String(error));
    if (!GlobalErrorView) return null;
    const render = GlobalErrorView as unknown as (p: { error: Error; reset: () => void }) => ReactNode;
    return <>{bodyContent(render({ error: err, reset: () => window.location.reload() }))}</>;
  }
  return {
    id: "root",
    path: "/",
    Component: Root,
    ErrorBoundary: RootError,
    HydrateFallback: () => null,
    children: [...(files.redirects ?? []), ...files.children, { path: "*", Component: NotFound }],
  };
}

/** next.config.ts `redirects()` (also listed for Firebase Hosting in docs/firebase/agents/spa.md). */
export function redirectRoute(path: string, to: (params: Record<string, string | undefined>) => string): RouteObject {
  function Redirect() {
    const params = useParams();
    const { search } = useLocation();
    return <ClientRedirect to={`${to(params)}${search}`} />;
  }
  return { path, Component: Redirect };
}
